def editor_ops(ops):
    text = ''
    undo, redo, out = [], [], []
    for op in ops:
        k = op[0]
        if k == 'type':
            undo.append(text); redo.clear(); text += op[1]
        elif k == 'delete':
            undo.append(text); redo.clear(); text = text[:max(0, len(text) - op[1])]
        elif k == 'undo':
            if undo:
                redo.append(text); text = undo.pop()
        elif k == 'redo':
            if redo:
                undo.append(text); text = redo.pop()
        else:
            out.append(text)
    return out
